func (sdk *LiveNamespace) AcceptSession(ctx context.Context, params AcceptLiveSessionParams, opts ...RequestOption) (any, error) {
	return AcceptLiveSession(ctx, sdk.config, params, opts...)
}

// ForkSession fork a stored Live session onto a new WebRTC connection.
